<template><div class="row" :class="message.type"><div class="bubble"><div v-if="message.type==='assistant'&&message.reasoning" class="reason"><button @click="show=!show">思考 {{show?'⌄':'›'}}</button><pre v-if="show">{{message.reasoning}}</pre></div><MarkdownView v-if="message.content" :content="message.content"/><div v-else-if="message.type==='assistant'&&message.status==='streaming'" class="wait">正在生成…</div><div v-if="message.error" class="error">{{message.error}}</div><div v-if="message.type==='assistant'&&(message.provider||message.usage)" class="meta">{{message.provider}}<span v-if="message.model"> · {{message.model}}</span><span v-if="message.ttft_ms"> · 首字 {{message.ttft_ms}}ms</span><span v-if="message.duration_ms"> · {{(message.duration_ms/1000).toFixed(1)}}s</span></div></div></div></template>
<script setup lang="ts">import { ref } from 'vue';import MarkdownView from './MarkdownView.vue';import type { ChatMessage } from '../stores/chat';defineProps<{message:ChatMessage}>();const show=ref(false)</script>
